queries.query:
PREFIX ma: <https://mediaarts-db.artmuseums.go.jp/data/property#>
SELECT ?book ?p ?o WHERE {
  VALUES ?book { <https://mediaarts-db.artmuseums.go.jp/id/M1032568> }
  ?book ?p ?o
} ORDER BY ?p ?o LIMIT 200

SELECT DISTINCT ?graph WHERE {
  GRAPH ?graph {
    <https://mediaarts-db.artmuseums.go.jp/id/M381096> ?p ?o
  }
} LIMIT 10

PREFIX schema: <https://schema.org/>
PREFIX class: <https://mediaarts-db.artmuseums.go.jp/data/class#>
SELECT ?book ?p ?o WHERE {
  ?book a class:MangaBook ; schema:identifier "M381096" ; ?p ?o
} ORDER BY ?p ?o LIMIT 300

PREFIX schema: <https://schema.org/>
PREFIX class: <https://mediaarts-db.artmuseums.go.jp/data/class#>
SELECT ?book ?title ?volume ?series ?seriesTitle ?work ?publisher ?label ?date ?creator WHERE {
  ?book a class:MangaBook ; schema:isbn "9784832241190" .
  OPTIONAL { ?book schema:name ?title . FILTER(LANG(?title) = "") }
  OPTIONAL { ?book schema:volumeNumber ?volume }
  OPTIONAL {
    ?book schema:isPartOf ?series . ?series a class:MangaBookSeries .
    OPTIONAL { ?series schema:name ?seriesTitle . FILTER(LANG(?seriesTitle) = "") }
    OPTIONAL { ?series schema:isPartOf ?work . ?work a class:MangaWork }
  }
  OPTIONAL { ?book schema:publisher ?publisher }
  OPTIONAL { ?book schema:brand ?label . FILTER(LANG(?label) = "") }
  OPTIONAL { ?book schema:datePublished ?date }
  OPTIONAL { ?book schema:creator ?creator . FILTER(LANG(?creator) = "") }
} LIMIT 100

PREFIX schema: <https://schema.org/>
PREFIX class: <https://mediaarts-db.artmuseums.go.jp/data/class#>
SELECT ?book ?isbn (DATATYPE(?isbn) AS ?datatype) WHERE {
  VALUES ?isbn { "9784592880714" "4592880714" "4-592-88071-4" }
  ?book a class:MangaBook ; schema:isbn ?isbn
} LIMIT 20

PREFIX schema: <https://schema.org/>
PREFIX dcterms: <http://purl.org/dc/terms/>
SELECT ?book ?relation ?node ?p ?o WHERE {
  VALUES ?book { <https://mediaarts-db.artmuseums.go.jp/id/M381096> }
  VALUES ?relation { dcterms:creator dcterms:publisher schema:provider }
  ?book ?relation ?node . FILTER(isIRI(?node) || isBlank(?node))
  ?node ?p ?o
} ORDER BY ?node ?p ?o LIMIT 300

SELECT ?book ?p ?o WHERE {
  VALUES ?book {
    <https://mediaarts-db.artmuseums.go.jp/id/M381096>
    <https://mediaarts-db.bunka.go.jp/id/M381096>
  }
  VALUES ?p {
    <http://www.w3.org/1999/02/22-rdf-syntax-ns#type>
    <http://schema.org/name>
    <https://schema.org/name>
  }
  ?book ?p ?o
} LIMIT 20

SELECT ?p ?o WHERE {
  <https://mediaarts-db.artmuseums.go.jp/id/M381096> ?p ?o
} ORDER BY ?p ?o LIMIT 300

PREFIX class: <https://mediaarts-db.artmuseums.go.jp/data/class#>
SELECT ?s ?p ?o WHERE {
  { SELECT ?s WHERE { ?s a class:MangaBook } LIMIT 1 }
  ?s ?p ?o
} LIMIT 200

PREFIX schema: <https://schema.org/>
PREFIX class: <https://mediaarts-db.artmuseums.go.jp/data/class#>
SELECT ?series ?p ?o WHERE {
  <https://mediaarts-db.artmuseums.go.jp/id/M381096> schema:isPartOf ?series .
  ?series a class:MangaBookSeries ; ?p ?o
} ORDER BY ?p ?o LIMIT 300

PREFIX schema: <https://schema.org/>
PREFIX class: <https://mediaarts-db.artmuseums.go.jp/data/class#>
SELECT ?book ?title ?volume WHERE {
  ?book a class:MangaBook ; schema:isPartOf <https://mediaarts-db.artmuseums.go.jp/id/C334830> .
  OPTIONAL { ?book schema:name ?title . FILTER(LANG(?title) = "") }
  OPTIONAL { ?book schema:volumeNumber ?volume }
} ORDER BY ?book LIMIT 20 OFFSET 0

PREFIX schema: <https://schema.org/>
SELECT ?book ?title (LANG(?title) AS ?lang) (DATATYPE(?title) AS ?datatype) WHERE {
  VALUES ?book { <https://mediaarts-db.artmuseums.go.jp/id/M381096> }
  ?book schema:name ?title .
  FILTER(CONTAINS(STR(?title), "ご注文"))
  FILTER(REGEX(STR(?title), "うさぎ", "i"))
  FILTER(CONTAINS(LCASE(STR(?title)), LCASE("ご注文")))
} LIMIT 10

PREFIX schema: <https://schema.org/>
PREFIX class: <https://mediaarts-db.artmuseums.go.jp/data/class#>
SELECT ?book ?title ?volume WHERE {
  ?book a class:MangaBook ; schema:name "ご注文はうさぎですか?" ; schema:name ?title .
  OPTIONAL { ?book schema:volumeNumber ?volume }
} ORDER BY ?book ?title LIMIT 40 OFFSET 0

PREFIX schema: <https://schema.org/>
PREFIX class: <https://mediaarts-db.artmuseums.go.jp/data/class#>
SELECT ?book ?title ?volume WHERE {
  ?book a class:MangaBook ; schema:name "ご注文はうさぎですか?" ; schema:name ?title .
  OPTIONAL { ?book schema:volumeNumber ?volume }
} ORDER BY ?book ?title LIMIT 2 OFFSET 2

PREFIX schema: <https://schema.org/>
PREFIX class: <https://mediaarts-db.artmuseums.go.jp/data/class#>
SELECT ?book ?series ?work ?title WHERE {
  VALUES ?book { <https://mediaarts-db.artmuseums.go.jp/id/M381096> }
  ?book a class:MangaBook ; schema:isPartOf ?series .
  ?series a class:MangaBookSeries ; schema:isPartOf ?work .
  ?work a class:MangaWork .
  OPTIONAL { ?work schema:name ?title }
} LIMIT 20

SELECT ?class ?s WHERE {
  VALUES ?class {
    <https://mediaarts-db.artmuseums.go.jp/data/class#MangaWork>
    <https://mediaarts-db.artmuseums.go.jp/data/class/MangaWork>
    <https://mediaarts-db.bunka.go.jp/data/class#MangaWork>
    <https://mediaarts-db.artmuseums.go.jp/data/class#Work>
  }
  ?s a ?class
} LIMIT 10
